 const token=async()=>{const user=getAuth(firebaseApp).currentUser;if(!user)throw new Error('Your Google session is not ready. Sign out and sign in again.');return user.getIdToken()}
 useEffect(()=>{(async()=>{try{const t=await token();const r=await fetch('/api/secrets',{headers:{Authorization:`Bearer ${t}`},cache:'no-store'});const data=await r.json();if(!r.ok)throw new Error(data.error||`Credential status failed (${r.status})`);setStatus(data.configured||{})}catch(e){setError(e.message)}finally{setLoading(false)}})()},[])
