 useEffect(()=>stop,[])
 const enable=async()=>{try{stop();const stream=await navigator.mediaDevices.getUserMedia({audio:input?{deviceId:{exact:input}}:true});streamRef.current=stream;const devices=await navigator.mediaDevices.enumerateDevices();setInputs(devices.filter(d=>d.kind==='audioinput'));setOutputs(devices.filter(d=>d.kind==='audiooutput'));setStatus('Microphone active');const ctx=new AudioContext(),source=ctx.createMediaStreamSource(stream),analyser=ctx.createAnalyser();source.connect(analyser);const data=new Uint8Array(analyser.frequencyBinCount);const tick=()=>{analyser.getByteFrequencyData(data);setLevel(Math.min(100,Math.round(data.reduce((a,b)=>a+b,0)/data.length)));frameRef.current=requestAnimationFrame(tick)};tick()}catch(e){setStatus(e.name==='NotAllowedError'?'Microphone permission denied':'Audio access failed')}
 }
